-- CURRENT DEPLOYED SCHEMA REFERENCE — not a migration or tested restore script.
-- Source: read-only PostgreSQL 17.6 catalogs, 2026-10-20 (Asia/Dhaka).
SET standard_conforming_strings = on;
SET search_path = pg_catalog, public;

CREATE TABLE "public"."notification_deliveries" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."notification_deliveries_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "notification_id" uuid NOT NULL,
  "subscription_id" bigint,
  "channel" text NOT NULL,
  "attempt_number" integer DEFAULT 1 NOT NULL,
  "delivery_status" text DEFAULT 'Pending'::text NOT NULL,
  "provider_message_id" text,
  "provider_status" text,
  "attempted_at" timestamp with time zone,
  "sent_at" timestamp with time zone,
  "delivered_at" timestamp with time zone,
  "failed_at" timestamp with time zone,
  "error_code" text,
  "error_message" text,
  "response_metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."notification_deliveries" OWNER TO "postgres";
COMMENT ON TABLE "public"."notification_deliveries" IS 'Per-channel and per-device delivery-attempt audit for each notification.';
COMMENT ON COLUMN "public"."notification_deliveries"."notification_id" IS 'Authoritative user notification associated with this delivery attempt.';
COMMENT ON COLUMN "public"."notification_deliveries"."subscription_id" IS 'Target device subscription when channel is WebPush.';
COMMENT ON COLUMN "public"."notification_deliveries"."delivery_status" IS 'Pending, Processing, Sent, Delivered, Failed, Skipped or Cancelled.';
COMMENT ON COLUMN "public"."notification_deliveries"."response_metadata" IS 'Non-secret provider response metadata used for delivery diagnostics.';
